#!/bin/bash
# Task 144-w10-barrier -- meshsim sim/ WORKER10 (branch sim-w10; kit: after 0b8bbd8). TIMING TASK: keep the box quiet while it runs.
# The barrier's cost (W10), measured bare before choosing a lighter one: (1) the barrier alone, T threads doing only
# Barrier::wait (W4's spin-then-yield and pure spin), us per round; (2) the bare interval: T domains each a unit stepping
# every cycle, a ring of Links of 3, rate 0 and 0.3, plain and --time. 2, 3, 4, 6, 8 and every P CPU. One revision
# (0b8bbd8). 5 repeats. ~4 min.
# From an embedded kit (sim/ at each revision named above). Writes only results/144-w10-barrier/. Scratch in /tmp, removed first
# and at the end. Safe to re-run.
set -u
cd "$(dirname "$0")/.."
REPO=$PWD; RES=$REPO/results/144-w10-barrier; mkdir -p "$RES"; rm -f "$RES/raw.txt"
W=/tmp/w10-144-w10-barrier; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "48ed2c0deeaa484e4b5ba6f2f12d73d36f1040eeab806df6422442ec9f8d8f8c" ] || { echo "kit sha256 mismatch (want 48ed2c0deeaa484e4b5ba6f2f12d73d36f1040eeab806df6422442ec9f8d8f8c)"; exit 2; }
mkdir -p "$W/kit" && tar -xzf "$W/kit.tgz" -C "$W/kit" || exit 2
KITS="after"
FAILS=0; FAIL=0
sec() { echo; echo "==== $*  [$(date +%T)]"; }
verdict() { echo "VERDICT $1: $2"; [ "$2" = PASS ] || FAIL=1; }
START=$(date +%s)
{
sec "machine (D21)"; . "$W/kit/after/sim/tools/machine.sh" "${QUEST_P_CPUS:-}" "${QUEST_E_CPUS:-}"; machine_record "$RES/machine.txt"; uptime
echo "kit: after 0b8bbd8"
# Shared by W10's task bodies. run TAG CPUSET cmd...: one run under taskset (and perf stat when PERF=1: cycles,
# instructions, L1d load misses, LLC load misses, summed per core type); appends "TAG <bench line> [perf: ...]" to
# $RES/raw.txt. field NAME: a key=value field of stdin's lines.
run() {
  local tag=$1 cpus=$2; shift 2
  command -v perf > /dev/null || PERF=0
  if [ "${PERF:-0}" = 1 ]; then
    taskset -c "$cpus" perf stat -x, -e cycles,instructions,L1-dcache-load-misses,LLC-load-misses -o "$W/perf.csv" -- "$@" \
      > "$W/out.txt" 2> "$W/err.txt"
  else
    taskset -c "$cpus" "$@" > "$W/out.txt" 2> "$W/err.txt"
  fi
  local rc=$?
  local line; line=$(grep -E '^(threads|chip) ' "$W/out.txt" | tail -1)
  if [ $rc -ne 0 ] || [ -z "$line" ]; then echo "RUNFAIL $tag rc=$rc: $*"; head -5 "$W/err.txt"; FAILS=$((FAILS + 1)); return 1; fi
  local pc=""
  [ "${PERF:-0}" = 1 ] && pc=" perf: $(awk -F, '$1 ~ /^[0-9]+$/ { n=split($3,a,"/"); ev=(n>1)?a[2]:a[1]; k=(a[1]=="cpu_atom")?"atom":"core";
      v[k "_" ev]+=$1 } END { for (x in v) printf "%s=%s ", x, v[x] }' "$W/perf.csv")"
  echo "$tag $line$pc" | tee -a "$RES/raw.txt"
}
field() { grep -o "$1=[^ ]*" | cut -d= -f2; }
# med TAG FIELD: the median of FIELD over raw.txt's lines starting "TAG "
med() { grep "^$1 " "$RES/raw.txt" | field "$2" | sort -g | awk '{ a[NR]=$1 } END { if (NR) print a[int((NR+1)/2)]; else print "-" }'; }
# Task body (WORKER10): what the barrier costs, alone and with the engine's per-interval work, against the chip's useful
# work (0.156 us a cycle a thread at 6 threads: 0.47 us an interval of 3). (1) bench_threads --form 3 --barrier-only:
# T threads doing nothing but the barrier (us per round), spin (W4's default 2000 pauses then yield) and pure spin.
# (2) --form 3: T domains, a unit each stepping every cycle, a ring of Links of 3 (rate 0: no words; 0.3: some), with
# --time: the bare interval (publish, barrier, drain, clear, the engine's entry). REPS (default 5).
REPS=${REPS:-5}
sec "build (clang release, D18)"
for k in $KITS; do
  ( cd "$W/kit/$k/sim" && make -j8 CC_NAME=clang MODE=release build/clang-release/bench_threads > "$RES/build-$k.log" 2>&1 ) \
    || { tail -20 "$RES/build-$k.log"; verdict "build $k" FAIL; exit 1; }
done
NPC=$(count "$P_CPUS")
cpus_for() { local t=$1; if [ "$t" -le "$NPC" ]; then echo "$P_CPUS"; else echo "$ALL_CPUS"; fi; }
TS=; for t in 2 3 4 6 8 $NPC; do [ "$t" -le "$NPC" ] && [[ " $TS " != *" $t "* ]] && TS+="${TS:+ }$t"; done
for rep in $(seq $REPS); do for k in $KITS; do B=$W/kit/$k/sim/build/clang-release/bench_threads
  for t in $TS; do C=$(take $t "$PLACE"); TSET=$(cpus_for $t)
    run "$k bo-t$t-yield" "$TSET" $B --form 3 --barrier-only --threads $t --cycles 2000000 --cpus "$C"
    run "$k bo-t$t-spin" "$TSET" $B --form 3 --barrier-only --threads $t --cycles 2000000 --barrier spin --cpus "$C"
    for r in 0 0.3; do
      run "$k bare-t$t-r$r" "$TSET" $B --form 3 --threads $t --cycles 600000 --warmup 3000 --rate $r --cpus "$C"
      run "$k bare-t$t-r$r-timed" "$TSET" $B --form 3 --threads $t --cycles 600000 --warmup 3000 --rate $r --cpus "$C" --time
    done
  done
done; done
sec "summary (medians): us per barrier round alone; us per bare interval, and its timed breakdown (us per interval)"
for k in $KITS; do for t in $TS; do
  line="$k t$t barrier_only: yield=$(med "$k bo-t$t-yield" us_per_round) spin=$(med "$k bo-t$t-spin" us_per_round);"
  for r in 0 0.3; do
    u=$(med "$k bare-t$t-r$r" us_per_interval); line+=" bare(r$r)=$u ["
    for f in compute imbalance barrier_wait drain publish clear; do
      sh=$(med "$k bare-t$t-r$r-timed" $f); ut=$(med "$k bare-t$t-r$r-timed" us_per_interval)
      line+="$f=$(awk -v s=$sh -v u=$ut 'BEGIN { printf "%.3f", s * u }') "
    done
    line+="]"
  done
  echo "$line"
done; done | tee "$RES/summary.txt"
[ "$FAILS" = 0 ] && verdict "every run completed" PASS || verdict "every run completed ($FAILS failed)" FAIL
sec "done in $(($(date +%s) - START)) s"
} 2>&1 | tee "$RES/run.log"
grep '^VERDICT' "$RES/run.log" > "$RES/VERDICTS.txt"
rm -rf "$W"
grep -q ': FAIL$' "$RES/VERDICTS.txt" && exit 1
exit 0
